create extension if not exists pgcrypto;
create table if not exists public.xyz_admins(user_id uuid primary key references auth.users(id) on delete cascade,role text not null default 'admin' check(role in('admin','editor')),created_at timestamptz not null default now());
create or replace function public.xyz_is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.xyz_admins where user_id=auth.uid()); $$;
create table if not exists public.xyz_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,image_url text,sort_order int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.xyz_destinations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,region text,description text,image_url text,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.xyz_packages(id uuid primary key default gen_random_uuid(),category_id uuid references public.xyz_categories(id) on delete set null,destination_id uuid references public.xyz_destinations(id) on delete set null,title text not null,slug text unique not null,short_description text,description text,price numeric(12,2),currency text default 'USD',duration_days int,difficulty text,max_altitude_m int,group_size text,best_season text,hero_image_url text,gallery_urls jsonb default '[]',itinerary jsonb default '[]',includes jsonb default '[]',excludes jsonb default '[]',featured boolean default false,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.xyz_bookings(id uuid primary key default gen_random_uuid(),package_id uuid references public.xyz_packages(id) on delete set null,customer_name text not null,email text,phone text,country text,travelers int not null default 1,travel_date date,message text,status text not null default 'new' check(status in('new','contacted','confirmed','cancelled','completed')),created_at timestamptz default now());
create table if not exists public.xyz_reviews(id uuid primary key default gen_random_uuid(),package_id uuid references public.xyz_packages(id) on delete cascade,customer_name text not null,country text,rating int not null check(rating between 1 and 5),review text not null,is_published boolean default false,created_at timestamptz default now());
create table if not exists public.xyz_blog_posts(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,excerpt text,content text,cover_image_url text,published boolean default false,published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.xyz_site_settings(id boolean primary key default true,company_name text not null default 'XYZ Treks & Tours',tagline text default 'Explore • Experience • Discover',phone text,whatsapp text,email text,address text default 'Kathmandu, Nepal',logo_url text,facebook_url text,instagram_url text,youtube_url text,updated_at timestamptz default now());
insert into public.xyz_site_settings(id) values(true) on conflict(id) do nothing;
insert into public.xyz_categories(name,slug,sort_order) values('Trekking','trekking',1),('Tours','tours',2),('Peak Climbing','peak-climbing',3),('Helicopter Tours','helicopter-tours',4) on conflict(slug) do nothing;
insert into public.xyz_destinations(name,slug,region) values('Everest Region','everest-region','Khumbu'),('Annapurna Region','annapurna-region','Gandaki'),('Langtang Region','langtang-region','Bagmati'),('Manaslu Region','manaslu-region','Gorkha'),('Kathmandu Valley','kathmandu-valley','Bagmati') on conflict(slug) do nothing;
insert into public.xyz_packages(title,slug,short_description,description,price,duration_days,difficulty,max_altitude_m,group_size,best_season,featured) values('Everest Base Camp Trek','everest-base-camp-trek','A legendary journey into the Khumbu Himalaya.','Experience Sherpa culture and dramatic mountain scenery.',1499,14,'Moderate to Challenging',5364,'2–12','March–May, September–November',true),('Annapurna Base Camp Trek','annapurna-base-camp-trek','A scenic Himalayan trek.','Mountain landscapes, local culture and hot springs.',899,10,'Moderate',4130,'2–12','March–May, September–November',true),('Kathmandu Cultural Tour','kathmandu-cultural-tour','Discover heritage sites and living culture.','A flexible cultural itinerary covering Kathmandu Valley highlights.',499,5,'Easy',1400,'1–20','All year',false) on conflict(slug) do nothing;
alter table public.xyz_admins enable row level security;alter table public.xyz_categories enable row level security;alter table public.xyz_destinations enable row level security;alter table public.xyz_packages enable row level security;alter table public.xyz_bookings enable row level security;alter table public.xyz_reviews enable row level security;alter table public.xyz_blog_posts enable row level security;alter table public.xyz_site_settings enable row level security;
create policy xyz_categories_public_select on public.xyz_categories for select using(is_active=true or public.xyz_is_admin());create policy xyz_destinations_public_select on public.xyz_destinations for select using(is_active=true or public.xyz_is_admin());create policy xyz_packages_public_select on public.xyz_packages for select using(is_active=true or public.xyz_is_admin());create policy xyz_reviews_public_select on public.xyz_reviews for select using(is_published=true or public.xyz_is_admin());create policy xyz_blog_public_select on public.xyz_blog_posts for select using(published=true or public.xyz_is_admin());create policy xyz_settings_public_select on public.xyz_site_settings for select using(true);create policy xyz_bookings_public_insert on public.xyz_bookings for insert with check(true);create policy xyz_admins_self_select on public.xyz_admins for select using(user_id=auth.uid() or public.xyz_is_admin());create policy xyz_categories_admin_write on public.xyz_categories for all using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_destinations_admin_write on public.xyz_destinations for all using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_packages_admin_write on public.xyz_packages for all using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_bookings_admin_select on public.xyz_bookings for select using(public.xyz_is_admin());create policy xyz_bookings_admin_update on public.xyz_bookings for update using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_reviews_admin_write on public.xyz_reviews for all using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_blog_admin_write on public.xyz_blog_posts for all using(public.xyz_is_admin()) with check(public.xyz_is_admin());create policy xyz_settings_admin_update on public.xyz_site_settings for update using(public.xyz_is_admin()) with check(public.xyz_is_admin());
grant usage on schema public to anon,authenticated;grant select on public.xyz_categories,public.xyz_destinations,public.xyz_packages,public.xyz_reviews,public.xyz_blog_posts,public.xyz_site_settings to anon,authenticated;grant insert on public.xyz_bookings to anon,authenticated;grant select,insert,update,delete on public.xyz_categories,public.xyz_destinations,public.xyz_packages,public.xyz_reviews,public.xyz_blog_posts,public.xyz_site_settings to authenticated;grant select,update on public.xyz_bookings to authenticated;grant select on public.xyz_admins to authenticated;revoke execute on function public.xyz_is_admin() from anon,authenticated;grant execute on function public.xyz_is_admin() to authenticated;
